## Steps

### Step 1: Schema — lessons.db tables

Single SQL migration file. No separate `migrations/` directory since LessonsDb manages its own schema inline (keeps it self-contained; the per-workspace migrations/ dir is an artifact of `Db`'s longer history).

```sql
CREATE TABLE IF NOT EXISTS schema_migrations (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    name         TEXT    NOT NULL UNIQUE,
    content_hash TEXT    NOT NULL,
    applied_at   TEXT    NOT NULL
);

CREATE TABLE lessons (
    id              TEXT    NOT NULL PRIMARY KEY,  -- UUIDv7
    text            TEXT    NOT NULL,
    created_by      TEXT    NOT NULL DEFAULT 'agent',
    created_at      TEXT    NOT NULL DEFAULT (datetime('now')),
    project_origin  TEXT,
    verified        INTEGER NOT NULL DEFAULT 0,
    confidence      INTEGER NOT NULL DEFAULT 0,
    last_surfaced   TEXT,
    last_cited      TEXT,
    archived        INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE anchors (
    id        INTEGER PRIMARY KEY AUTOINCREMENT,
    lesson_id TEXT    NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,
    kind      TEXT    NOT NULL,   -- 'symbol', 'file', 'import_pattern', 'directory'
    value     TEXT    NOT NULL
);
CREATE INDEX idx_anchors_kind_value ON anchors(kind, value);
CREATE INDEX idx_anchors_lesson_id ON anchors(lesson_id);

CREATE TABLE categories (
    id        INTEGER PRIMARY KEY AUTOINCREMENT,
    lesson_id TEXT    NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,
    tag       TEXT    NOT NULL,
    UNIQUE(lesson_id, tag)
);

CREATE TABLE citations (
    id        INTEGER PRIMARY KEY AUTOINCREMENT,
    lesson_id TEXT    NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,
    task_id   TEXT    NOT NULL,
    field     TEXT,
    cited_at  TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX idx_citations_lesson_id ON citations(lesson_id);
```

### Step 2: LessonsDb struct + migration runner

`src/lessons.rs`. Single `Mutex<Connection>` (same pattern as `Db`). Own migration runner with blake3 content hashing.

```rust
use parking_lot::Mutex;
use rusqlite::{Connection, params};
use crate::error::{Result, SutraError};
use std::path::{Path, PathBuf};

pub struct LessonsDb {
    conn: Mutex<Connection>,
}

const MIGRATIONS: &[(&str, &str)] = &[
    ("0001_initial", include_str!("lessons_schema.sql")),
];

impl LessonsDb {
    pub fn open(db_dir: &Path) -> Result<Self> {
        std::fs::create_dir_all(db_dir).map_err(|e| {
            SutraError::Internal(format!("cannot create {}: {e}", db_dir.display()))
        })?;
        let db_path = db_dir.join("lessons.db");
        let conn = Connection::open(&db_path)?;
        conn.execute_batch(
            "PRAGMA journal_mode = WAL;\
             PRAGMA synchronous = NORMAL;\
             PRAGMA foreign_keys = ON;\
             PRAGMA busy_timeout = 5000;",
        )?;
        let db = Self { conn: Mutex::new(conn) };
        db.run_migrations()?;
        Ok(db)
    }

    fn run_migrations(&self) -> Result<()> {
        let conn = self.conn.lock();
        conn.execute_batch(
            "CREATE TABLE IF NOT EXISTS schema_migrations (
                 id           INTEGER PRIMARY KEY AUTOINCREMENT,
                 name         TEXT    NOT NULL UNIQUE,
                 content_hash TEXT    NOT NULL,
                 applied_at   TEXT    NOT NULL
             )",
        )?;
        for &(name, sql) in MIGRATIONS {
            let hash = blake3::hash(sql.as_bytes()).to_hex().to_string();
            let existing: Option<String> = conn
                .query_row(
                    "SELECT content_hash FROM schema_migrations WHERE name = ?1",
                    params![name], |row| row.get(0),
                ).ok();
            if let Some(stored) = existing {
                if stored != hash {
                    return Err(SutraError::Internal(format!(
                        "lessons migration `{name}` hash mismatch"
                    )));
                }
                continue;
            }
            conn.execute_batch(sql)?;
            conn.execute(
                "INSERT INTO schema_migrations (name, content_hash, applied_at) \
                 VALUES (?1, ?2, datetime('now'))",
                params![name, hash],
            )?;
        }
        Ok(())
    }
}
```

The migration SQL will live in `src/lessons_schema.sql` (loaded via `include_str!`). Contains the `CREATE TABLE` statements from Step 1 minus the `schema_migrations` table (that's created by the runner).

### Step 3: `LessonsDb::store()` — write path

Accepts text + location anchors + optional metadata. Generates UUIDv7, inserts lesson row + anchor rows in a transaction.

```rust
pub struct StoreLessonParams<'a> {
    pub text: &'a str,
    pub anchors: &'a [(AnchorKind, &'a str)],  // (kind, value) pairs
    pub categories: &'a [&'a str],
    pub source_task_ids: &'a [&'a str],
    pub project_origin: Option<&'a str>,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum AnchorKind {
    Symbol,
    File,
    ImportPattern,
    Directory,
}

impl LessonsDb {
    pub fn store(&self, params: &StoreLessonParams<'_>) -> Result<String> {
        let conn = self.conn.lock();
        let tx = conn.unchecked_transaction()?;
        let id = uuid::Uuid::now_v7().to_string();

        tx.execute(
            "INSERT INTO lessons (id, text, project_origin) VALUES (?1, ?2, ?3)",
            params![id, params.text, params.project_origin],
        )?;

        for (kind, value) in params.anchors {
            tx.execute(
                "INSERT INTO anchors (lesson_id, kind, value) VALUES (?1, ?2, ?3)",
                params![id, kind.as_str(), value],
            )?;
        }

        for tag in params.categories {
            tx.execute(
                "INSERT OR IGNORE INTO categories (lesson_id, tag) VALUES (?1, ?2)",
                params![id, tag],
            )?;
        }

        tx.commit()?;
        Ok(id)
    }
}
```

### Step 4: `LessonsDb::query_for_context()` — read path

For this slice: exact match on `anchors.kind = 'symbol' AND anchors.value = ?`. Returns matching lessons (non-archived only). Updates `last_surfaced`.

```rust
#[derive(Debug, Clone, Serialize)]
pub struct SurfacedLesson {
    pub id: String,
    pub text: String,
    pub verified: bool,
    pub confidence: i64,
    pub project_origin: Option<String>,
    pub created_at: String,
}

impl LessonsDb {
    pub fn query_for_context(&self, symbol_name: &str) -> Result<Vec<SurfacedLesson>> {
        let conn = self.conn.lock();
        let mut stmt = conn.prepare(
            "SELECT l.id, l.text, l.verified, l.confidence,
                    l.project_origin, l.created_at
             FROM lessons l
             JOIN anchors a ON a.lesson_id = l.id
             WHERE a.kind = 'symbol' AND a.value = ?1
               AND l.archived = 0
             ORDER BY l.verified DESC, l.confidence DESC",
        )?;
        let lessons: Vec<SurfacedLesson> = stmt.query_map(params![symbol_name], |row| {
            Ok(SurfacedLesson {
                id: row.get(0)?,
                text: row.get(1)?,
                verified: row.get::<_, i64>(2)? != 0,
                confidence: row.get(3)?,
                project_origin: row.get(4)?,
                created_at: row.get(5)?,
            })
        })?.collect::<std::result::Result<Vec<_>, _>>()?;

        // Update last_surfaced for retrieved lessons
        if !lessons.is_empty() {
            let ids: Vec<&str> = lessons.iter().map(|l| l.id.as_str()).collect();
            let placeholders = ids.iter().map(|_| "?").collect::<Vec<_>>().join(",");
            conn.execute(
                &format!(
                    "UPDATE lessons SET last_surfaced = datetime('now') WHERE id IN ({placeholders})"
                ),
                rusqlite::params_from_iter(ids.iter()),
            )?;
        }

        Ok(lessons)
    }
}
```

