### Step 6: `sutra_remember` tool

**`src/tools/remember.rs`:**
```rust
#[derive(Debug, Deserialize, JsonSchema)]
pub struct RememberArgs {
    pub text: String,
    #[schemars(description = "Location anchors: symbol names or file paths this lesson applies to")]
    pub location_anchors: Vec<LocationAnchor>,
    #[serde(default)]
    pub source_tasks: Option<Vec<String>>,
    #[serde(default)]
    pub project_origin: Option<String>,
    #[serde(default)]
    pub categories: Option<Vec<String>>,
}

#[derive(Debug, Deserialize, JsonSchema)]
pub struct LocationAnchor {
    pub kind: String,   // "symbol" or "file"
    pub value: String,
}

pub fn handle(lessons_db: &LessonsDb, args: &RememberArgs) -> Result<serde_json::Value> {
    let anchors: Vec<(AnchorKind, &str)> = args.location_anchors.iter()
        .map(|a| {
            let kind = match a.kind.as_str() {
                "symbol" => AnchorKind::Symbol,
                "file" => AnchorKind::File,
                _ => AnchorKind::Symbol, // default
            };
            (kind, a.value.as_str())
        })
        .collect();
    let cats: Vec<&str> = args.categories.as_deref().unwrap_or(&[])
        .iter().map(|s| s.as_str()).collect();
    let tasks: Vec<&str> = args.source_tasks.as_deref().unwrap_or(&[])
        .iter().map(|s| s.as_str()).collect();

    let id = lessons_db.store(&StoreLessonParams {
        text: &args.text,
        anchors: &anchors,
        categories: &cats,
        source_task_ids: &tasks,
        project_origin: args.project_origin.as_deref(),
    })?;

    Ok(json!({
        "stored": true,
        "lesson_id": id,
        "anchor_count": args.location_anchors.len(),
    }))
}
```

**`src/mcp.rs`** — add `#[tool]` method (no workspace context needed — lessons are cross-workspace):
```rust
#[tool(description = "Store a code-anchored lesson (negative knowledge). \
    Provide text describing what you learned and location anchors \
    (symbol names or file paths) so the lesson surfaces in future reads.")]
pub async fn sutra_remember(
    &self,
    Parameters(args): Parameters<tools::remember::RememberArgs>,
) -> Result<String, ErrorData> {
    let result = tools::remember::handle(&self.lessons_db, &args)
        .map_err(sutra_to_rmcp)?;
    to_compact_json(result)
}
```

### Step 7: Inject lessons into `sutra_read`

**`src/tools/read.rs`** — add `lessons_db: Option<&LessonsDb>` parameter. After the happy-path `result` JSON is built (line 131), query and inject:

```rust
pub fn handle(
    db: &Db,
    workspace_root: &Path,
    symbol: &str,
    context_lines: Option<usize>,
    limit: Option<usize>,
    full: bool,
    is_stale: bool,
    lessons_db: Option<&LessonsDb>,  // new parameter
) -> Result<serde_json::Value> {
    // ... existing code through line 148 ...

    // Inject lessons (after building `result`, before returning)
    if let Some(ldb) = lessons_db {
        let lessons = ldb.query_for_context(&sym.qualified_name)?;
        if !lessons.is_empty() {
            result["lessons"] = serde_json::to_value(&lessons)
                .unwrap_or_default();
        }
    }

    Ok(result)
}
```

